{"python":"def pilot_policy(trace):
    import json
    from typing import Set, Dict, List, Any

    # Policy mapping: slot -> allowed categories
    policy: Dict[str, List[str]] = {
        'slot:audit': ['FINANCIAL', 'AUTH'],
        'slot:bank': ['EMPLOYEE', 'AUTH'],
        'slot:processor': ['AUTH', 'UNVERIFIED'],
        'slot:public': ['EMPLOYEE', 'FINANCIAL', 'AUTH'],
        'slot:regulator': ['UNVERIFIED']
    }

    def get_allowed(slot: str) -> Set[str]:
        return set(policy.get(slot, []))

    def check_write(label_cats: Set[str], slot: str) -> bool:
        allowed = get_allowed(slot)
        if not allowed:
            return True  # no restrictions
        return label_cats.issubset(allowed)

    if not trace:
        return None

    action, label = trace[-1]
    name = action.name
    args = json.loads(action.arguments)
    cats = label.subset

    # Tool: intake/import_expense (intake agent)
    if name == 'intake/import_expense':
        # Writes to slot:claim only (no policy restriction)
        return None

    # Tool: reviewer/review_claim (reviewer agent)
    elif name == 'reviewer/review_claim':
        # Writes to slot:approved (no policy restriction)
        return None

    # Tool: clerk/assemble_packet (clerk agent)
    elif name == 'clerk/assemble_packet':
        # Writes to slot:packet (no policy restriction)
        return None

    # Tool: claims/submit_claim (claims agent)
    elif name == 'claims/submit_claim':
        route = args.get('route')
        copy = args.get('copy')
        include = args.get('include')
        source = args.get('source')

        # Determine primary destination based on route
        primary_slot = None
        if route == 'counterparty':
            primary_slot = 'slot:processor'
        elif route == 'release':
            primary_slot = 'slot:public'

        # Determine copy destinations
        copy_slots = []
        if copy == 'audit':
            copy_slots.append('slot:audit')
        elif copy == 'counterparty':
            copy_slots.append('slot:processor')
        elif copy == 'public':
            copy_slots.append('slot:public')

        # All write slots (primary + copies, deduplicated)
        write_slots = set()
        if primary_slot:
            write_slots.add(primary_slot)
        for s in copy_slots:
            write_slots.add(s)

        # Check each write slot
        for slot in write_slots:
            if not check_write(cats, slot):
                raise PolicyViolation(f'Label {cats} violates policy for {slot}')
        return None

    # Tool: treasury/submit_claim (treasury agent)
    elif name == 'treasury/submit_claim':
        route = args.get('route')
        copy = args.get('copy')
        include = args.get('include')
        source = args.get('source')

        # Determine primary destination based on route
        primary_slot = None
        if route == 'counterparty':
            primary_slot = 'slot:bank'
        elif route == 'release':
            primary_slot = 'slot:regulator'

        # Determine copy destinations
        copy_slots = []
        if copy == 'audit':
            copy_slots.append('slot:audit')
        elif copy == 'counterparty':
            copy_slots.append('slot:bank')
        elif copy == 'public':
            copy_slots.append('slot:public')

        # All write slots
        write_slots = set()
        if primary_slot:
            write_slots.add(primary_slot)
        for s in copy_slots:
            write_slots.add(s)

        # Check each write slot
        for slot in write_slots:
            if not check_write(cats, slot):
                raise PolicyViolation(f'Label {cats} violates policy for {slot}')
        return None

    else:
        raise PolicyViolation(f'Unknown tool: {name}')}"}
